fn frame(t: i32) {
    host::display::clear(0x000005);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let r: i32 = 130;
    host::display::fill_rect(cx - 4, cy - 4, 8, 8, 0x554400);
    let mut k: i32 = 15;
    while k >= 0 {
        let a: i32 = t * 3 - k * 6;
        let x: i32 = cx + (r * host::math::cos(a)) / 256;
        let y: i32 = cy + (r * host::math::sin(a)) / 256;
        let b: i32 = 255 - k * 15;
        let s: i32 = 6 - k / 3;
        host::display::fill_rect(x - s / 2, y - s / 2, s, s, (b << 16) | (b << 8) | (b / 2));
        k = k - 1;
    }
    host::display::present();
}
